//! The .dsb flatbuffer schema — document format shared by file and wire roles (docs/design/dashbuf.md, docs/roadmap.md v2).
//!
//! Scope: a flattened node tree; fixed-size geometry plus the v0.2
//! flex layout vocabulary (mode NONE/H/V, per-axis hug/fill/fixed
//! sizing, gap, padding, alignment, min/max — docs/roadmap.md v0.2);
//! and the v0.3 paint vocabulary (docs/roadmap.md v0.3) held in a
//! document-level paint pool — solid fills, the four gradient kinds,
//! image fills, stroke with align, corner radii, clip. Schema source:
//! `schema/dashbuf.fbs`; Rust bindings are generated by `flatc` at
//! build time (see `build.rs`).

#[allow(clippy::all, dead_code)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/dashbuf_generated.rs"));
}

pub use generated::dashbuf::*;

/// `Node.parent`'s "root node" sentinel.
pub const NO_PARENT: u32 = u32::MAX;
/// `Node.paint_entry`'s "draws nothing" sentinel.
pub const NO_PAINT: u32 = u32::MAX;
/// `Node.text`'s "no text content" sentinel.
pub const NO_TEXT: u32 = u32::MAX;
/// `Node.text_style`'s "unstyled text" sentinel.
pub const NO_TEXT_STYLE: u32 = u32::MAX;
/// `Paint.shape_field`'s "parametric shape" sentinel (story B1): the paint
/// entry carries the implicit rounded box, not a baked field.
pub const NO_FIELD: u32 = u32::MAX;
